### 3.5 `voronoi.go` — dual (exact rational circumcenters)

```go
package main

import (
	"math"
	"math/big"
)

type PointF struct{ X, Y float64 }

type VoronoiDiagram struct {
	Sites    []PointF
	Vertices []PointF // circumcenters (then hull-ray far points)
	Edges    [][2]int
}

// Voronoi builds the dual: finite edges connect circumcenters of adjacent
// Delaunay triangles; hull edges become rays to a far finite point.
func (d *Delaunay) Voronoi(points []Point) VoronoiDiagram {
	vg := VoronoiDiagram{}
	for _, p := range points {
		vg.Sites = append(vg.Sites, PointF{float64(p.X), float64(p.Y)})
	}

	triIndex := map[int]int{}
	for i := range d.tris {
		if d.tris[i].alive {
			triIndex[i] = len(vg.Vertices)
			v := d.tris[i].v
			cx, cy := circumcenter(d.pts[v[0]], d.pts[v[1]], d.pts[v[2]])
			vg.Vertices = append(vg.Vertices, PointF{cx, cy})
		}
	}

	seen := map[[2]int]bool{}
	for i := range d.tris {
		if !d.tris[i].alive { continue }
		for e := 0; e < 3; e++ {
			n := d.tris[i].n[e]
			if n < 0 || !d.tris[n].alive { continue }
			a, b := d.tris[i].edge(e)
			key := [2]int{a, b}
			if key[0] > key[1] { key[0], key[1] = key[1], key[0] }
			if seen[key] { continue }
			seen[key] = true
			vg.Edges = append(vg.Edges, [2]int{triIndex[i], triIndex[n]})
		}
	}

	scale := 1e6 * (boundingDiag(points) + 1)
	for i := range d.tris {
		if !d.tris[i].alive { continue }
		for e := 0; e < 3; e++ {
			n := d.tris[i].n[e]
			if n >= 0 && d.tris[n].alive { continue }
			a, b := d.tris[i].edge(e)
			pa, pb := d.pts[a], d.pts[b]
			c := vg.Vertices[triIndex[i]]
			ex, ey := float64(pb.X-pa.X), float64(pb.Y-pa.Y)
			nx, ny := ey, -ex // outward normal (interior is left of a->b)
			norm := math.Hypot(nx, ny)
			if norm == 0 { continue }
			far := PointF{c.X + nx/norm*scale, c.Y + ny/norm*scale}
			vg.Vertices = append(vg.Vertices, far)
			vg.Edges = append(vg.Edges, [2]int{triIndex[i], len(vg.Vertices) - 1})
		}
	}
	return vg
}

// circumcenter computes the exact rational circumcenter then converts to float.
func circumcenter(a, b, c Point) (float64, float64) {
	ax, ay := big.NewInt(a.X), big.NewInt(a.Y)
	bx, by := big.NewInt(b.X), big.NewInt(b.Y)
	cx, cy := big.NewInt(c.X), big.NewInt(c.Y)

	a2 := new(big.Int).Add(new(big.Int).Mul(ax, ax), new(big.Int).Mul(ay, ay))
	b2 := new(big.Int).Add(new(big.Int).Mul(bx, bx), new(big.Int).Mul(by, by))
	c2 := new(big.Int).Add(new(big.Int).Mul(cx, cx), new(big.Int).Mul(cy, cy))

	term := new(big.Int).Mul(ax, new(big.Int).Sub(by, cy))
	term.Add(term, new(big.Int).Mul(bx, new(big.Int).Sub(cy, ay)))
	term.Add(term, new(big.Int).Mul(cx, new(big.Int).Sub(ay, by)))
	D := new(big.Int).Lsh(term, 1)
	if D.Sign() == 0 { return 0, 0 }

	ux := new(big.Int).Mul(a2, new(big.Int).Sub(by, cy))
	ux.Add(ux, new(big.Int).Mul(b2, new(big.Int).Sub(cy, ay)))
	ux.Add(ux, new(big.Int).Mul(c2, new(big.Int).Sub(ay, by)))

	uy := new(big.Int).Mul(a2, new(big.Int).Sub(cx, bx))
	uy.Add(uy, new(big.Int).Mul(b2, new(big.Int).Sub(ax, cx)))
	uy.Add(uy, new(big.Int).Mul(c2, new(big.Int).Sub(bx, ax)))

	fx, _ := new(big.Rat).SetFrac(ux, D).Float64()
	fy, _ := new(big.Rat).SetFrac(uy, D).Float64()
	return fx, fy
}

func boundingDiag(points []Point) float64 {
	if len(points) == 0 { return 0 }
	minx, miny, maxx, maxy := points[0].X, points[0].Y, points[0].X, points[0].Y
	for _, p := range points {
		if p.X < minx { minx = p.X }
		if p.X > maxx { maxx = p.X }
		if p.Y < miny { miny = p.Y }
		if p.Y > maxy { maxy = p.Y }
	}
	return math.Hypot(float64(maxx-minx), float64(maxy-miny))
}
